        for (let h = (0, config_1.targetToHundredths)(config_1.MIN_MULTIPLIER); h <= 200000; h += 7) {
            const m = h / config_1.MULTIPLIER_SCALE;
            assert.ok((0, config_1.theoreticalRTP)(m) <= 0.99 + 1e-12, `target ${m}: RTP ${(0, config_1.theoreticalRTP)(m)} > 0.99`);
        }
