        assert.ok((0, config_1.resultMultiplier)(99) < config_1.MAX_MULTIPLIER);
        assert.strictEqual((0, config_1.resultMultiplier)(config_1.RANGE - 1), 1);
        assert.strictEqual((0, config_1.resultMultiplier)(99000000), 1);
        assert.strictEqual((0, config_1.resultMultiplier)(98999999), 1);
