        assert.strictEqual((0, config_1.isTargetLegal)(1.00), false);
        assert.strictEqual((0, config_1.isTargetLegal)(config_1.MAX_MULTIPLIER), true);
        assert.strictEqual((0, config_1.isTargetLegal)(config_1.MAX_MULTIPLIER + 0.01), false);
        assert.strictEqual((0, config_1.isTargetLegal)(2.005), false);
